import pandas as pd
import streamlit as st

@st.cache_data
def charger(fichier) -> pd.DataFrame:
    return pd.read_csv(fichier)

fichier = st.file_uploader("Dépose un CSV", type="csv")
if fichier is not None:
    df = charger(fichier)
    colonnes = st.multiselect("Colonnes", df.columns.tolist(), default=df.columns[:3].tolist())
    tab_donnees, tab_stats = st.tabs(["Données", "Statistiques"])
    tab_donnees.dataframe(df[colonnes])
    tab_stats.write(df.describe())
    st.download_button("Télécharger la sélection", df[colonnes].to_csv(index=False), "selection.csv")
